import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse(`{"title":"What's New — v2.0 to v2.9.1","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/features/whats-new.md","filePath":"openshield-xdp/features/whats-new.md","lastUpdated":1786192116000}`),s={name:"openshield-xdp/features/whats-new.md"};function i(n,e,l,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="what-s-new-—-v2-0-to-v2-9-1" tabindex="-1">What&#39;s New — v2.0 to v2.9.1 <a class="header-anchor" href="#what-s-new-—-v2-0-to-v2-9-1" aria-label="Permalink to &quot;What&#39;s New — v2.0 to v2.9.1&quot;">​</a></h1><p>The feature changelog for the 2.x line. For the complete feature map see <a href="/pingless-studios-docs/openshield-xdp/features/">Everything OpenShield-XDP Does</a>.</p><h2 id="v2-9-1-—-target-list-hygiene" tabindex="-1">v2.9.1 — target-list hygiene <a class="header-anchor" href="#v2-9-1-—-target-list-hygiene" aria-label="Permalink to &quot;v2.9.1 — target-list hygiene&quot;">​</a></h2><ul><li>Multicast/broadcast destinations no longer appear in Top Targeted IPs / <code>/metrics/targets</code>.</li></ul><h2 id="v2-9-0-—-targeted-ip-visibility" tabindex="-1">v2.9.0 — targeted-IP visibility <a class="header-anchor" href="#v2-9-0-—-targeted-ip-visibility" aria-label="Permalink to &quot;v2.9.0 — targeted-IP visibility&quot;">​</a></h2><ul><li><strong>Which VPS IP is being attacked</strong> — per-destination-IP counters at wire speed; the TUI dashboard gets a <em>Top Targeted IPs</em> panel (live pps/bps/share), attack-end webhook reports get a <em>Top Targeted IPs</em> field, and the metrics API gains <code>GET /metrics/targets</code>. Built for dedicated hosts with routed/bridged VMs. <a href="/pingless-studios-docs/openshield-xdp/getting-started/vps-deployment">Deployment models</a></li></ul><h2 id="v2-8-3-—-audit-hardening-pass" tabindex="-1">v2.8.3 — audit hardening pass <a class="header-anchor" href="#v2-8-3-—-audit-hardening-pass" aria-label="Permalink to &quot;v2.8.3 — audit hardening pass&quot;">​</a></h2><ul><li><strong>Security:</strong> TCP <code>doff&lt;5</code> rejected (a doff=0 ACK could mint the established-connection mark without a real session); null-flag and Xmas scans now actually reach the flag validator; baseline anchor u64 wrap on busy links fixed; blind RSTs enforce the freshness window; API guard no longer drops multi-MSS request bodies or locks out IPv6 in allowlist-only mode.</li><li><strong>Correctness:</strong> IPv6 amp check honors extension headers; L7 runtime-promoted rules (slots 1-15) were silently inert; TUI ban countdown clock-domain mix; fetcher apply errors swallowed; config-reload RMW race; panic recovery reverting runtime edits; <code>spike_recovery_time</code>/<code>baseline_update_interval</code> validation (flap/panic paths).</li><li><strong>Performance:</strong> ban sweep loses ~400k syscalls/5s on feed-loaded hosts; bounded top-N map iterators; rate-limited new-source events with an exact kernel counter; async capped attacks.json persistence; no snapshot marshal with zero clients.</li></ul><h2 id="v2-8-2-—-new-source-metric-fix" tabindex="-1">v2.8.2 — new-source metric fix <a class="header-anchor" href="#v2-8-2-—-new-source-metric-fix" aria-label="Permalink to &quot;v2.8.2 — new-source metric fix&quot;">​</a></h2><ul><li><strong>New Src/s was stuck at 0</strong> — the userspace reader queried the single-entry new-source map with a per-CPU slice lookup, which always failed silently. The kernel now keeps a monotonic total alongside the 1s windowed count; the displayed rate is exact at any poll interval. The new-source temp-ban rule itself was verified firing live (400–540k new src/s during a rotating-spoof flood).</li></ul><h2 id="v2-8-1-—-repeat-offender-hardening-all-port-coverage" tabindex="-1">v2.8.1 — repeat-offender hardening, all-port coverage <a class="header-anchor" href="#v2-8-1-—-repeat-offender-hardening-all-port-coverage" aria-label="Permalink to &quot;v2.8.1 — repeat-offender hardening, all-port coverage&quot;">​</a></h2><ul><li><strong>Repeat-offender hardening</strong> — bans backed by <em>verified</em> heavy evidence (both PPS and BPS ≥ 3× threshold, no established TCP session) accrue a separate heavy-hit count: 2nd verified heavy ban = <strong>1 day</strong>, 3rd+ = <strong>7 days</strong> (<code>static.repeat_ban_duration_2/3</code>). Bulk transfers can never collect heavy marks; borderline crossers keep the normal ladder.</li><li><strong>All-port protection</strong> — <code>ct_server_port_max</code> default 65535: services on high ports (&gt;30000) are fully covered; outbound connections (apt/curl) still work via the SYN-ACK bootstrap.</li><li><strong>Scoring determinism fix</strong> — an odd <code>bpf_ktime</code> low bit was decoded as a spurious window reset on ~half of all packets; sampling and scoring are now exact.</li><li><strong>Heavy-evidence measurement fix</strong> — fast floods banned on 256-packet samples now have their <em>true</em> arrival rate extrapolated, so hardening actually engages on real floods.</li><li><strong>Port-cap starvation fix</strong> — attack-capped sources accrue suspicion before the cap drop (previously throttled forever, never banned).</li><li><strong>Ban-expiry clock fix</strong> — bans on hosts that suspend (laptops, suspended/migrated VMs) were reaped as instantly-expired; userspace now reads the same CLOCK_MONOTONIC as the kernel.</li></ul><h2 id="v2-8-0-—-smarter-classification-xdp-trace-api-guard-fixed-tui-chrome" tabindex="-1">v2.8.0 — smarter classification, XDP trace, API guard, fixed TUI chrome <a class="header-anchor" href="#v2-8-0-—-smarter-classification-xdp-trace-api-guard-fixed-tui-chrome" aria-label="Permalink to &quot;v2.8.0 — smarter classification, XDP trace, API guard, fixed TUI chrome&quot;">​</a></h2><ul><li><strong>Multi-signal classifier</strong> — new types (ACK_FLOOD, SYNACK_REFLECTION, FRAG_FLOOD, CARPET_BOMB, PORT_SCAN), UDP_AMPLIFICATION revived with subtypes (dns/ntp/ssdp/…), driven by new kernel counters (TCP flags, fragments, 12-slot reflector source-port histogram). Research-backed rules (FastNetMon, CICDDoS2019, Kitsune).</li><li><strong>XDP decision trace</strong> — every attack&#39;s forensics dir now has xdp-trace.log: each verdict with ns-accurate timestamps, sampled 1/64 per CPU, zero peacetime cost.</li><li><strong>API port guard</strong> — basic L7 for the metrics/control port: TCP-only + HTTP-method payloads + its own allowlist (metrics.whitelist), synced live.</li><li><strong>TUI fixed chrome</strong> — status/nav pinned top, keybind footer pinned bottom, every screen scrolls in a bounded viewport with scrollbars.</li><li><strong>Behavior engine</strong>: port fan-out scan detection. <strong>Baseline</strong>: anomalous days auto-flagged. Whitelisted bulk traffic no longer declares attacks.</li></ul><h2 id="v2-7-0-—-full-management-api-player-protection-hardened" tabindex="-1">v2.7.0 — full management API + player protection hardened <a class="header-anchor" href="#v2-7-0-—-full-management-api-player-protection-hardened" aria-label="Permalink to &quot;v2.7.0 — full management API + player protection hardened&quot;">​</a></h2><ul><li><strong>Management API</strong> — new read endpoints (/metrics/baseline, /metrics/geo, /metrics/alerter, /metrics/autofetch, /metrics/access, /metrics/schedule) and a <code>control_enabled</code>-gated control API: config get/set, whitelist/blacklist, geo toggle, baseline export/import/delete-day, autofetch, schedule, block-pattern, attack bulk-ban jobs. Everything the TUI does, over HTTP. <a href="/pingless-studios-docs/openshield-xdp/user-guide/metrics-api">API reference</a></li><li><strong>Player protection, flood-tested</strong> — the protected-source snapshot now fills in ~0.5s via batch map ops (plain iteration finished after the attack) and protects only proven pre-attack sources (established or first-seen ≥15s before declaration) — verified live: players flat through a rotating flood.</li></ul><h2 id="v2-6-0-—-adaptive-granularity-live-nic-tuning-toggle-baseline-day-summaries" tabindex="-1">v2.6.0 — adaptive granularity, live NIC-tuning toggle, baseline day summaries <a class="header-anchor" href="#v2-6-0-—-adaptive-granularity-live-nic-tuning-toggle-baseline-day-summaries" aria-label="Permalink to &quot;v2.6.0 — adaptive granularity, live NIC-tuning toggle, baseline day summaries&quot;">​</a></h2><ul><li><code>attack_poll_divisor</code> (default 4): polling jumps to 250ms during attacks only — zero peacetime CPU cost; <code>poll_interval</code> accepts fractional seconds.</li><li>NIC tuning toggle (<code>T</code> in the TUI) applies/reverts instantly, with the jitter tradeoff explained in the confirmation.</li><li>Baseline history rows show TCP/UDP splits and ▲/▼ deviation markers vs your median day.</li></ul><h2 id="v2-5-x-—-udp-player-protection-geo-ux-webhook-health-jitter-fix" tabindex="-1">v2.5.x — UDP player protection, geo UX, webhook health, jitter fix <a class="header-anchor" href="#v2-5-x-—-udp-player-protection-geo-ux-webhook-health-jitter-fix" aria-label="Permalink to &quot;v2.5.x — UDP player protection, geo UX, webhook health, jitter fix&quot;">​</a></h2><ul><li><strong>v2.5.0</strong> — protected-source snapshot map (Bedrock/UDP players survive floods), geo tab live job progress, webhook delivery panel in the Status tab, keybind pills + segmented status bar.</li><li><strong>v2.5.1</strong> — NIC tuning became opt-in (<code>nic_tuning</code>, default off): the coalescing it applied was the dedicated-host jitter source.</li></ul><h2 id="v2-4-x-—-baseline-memory-ml-tab-smart-preset-blending-honest-reports" tabindex="-1">v2.4.x — baseline memory (ML tab), smart preset blending, honest reports <a class="header-anchor" href="#v2-4-x-—-baseline-memory-ml-tab-smart-preset-blending-honest-reports" aria-label="Permalink to &quot;v2.4.x — baseline memory (ML tab), smart preset blending, honest reports&quot;">​</a></h2><ul><li><strong>30-day baseline memory</strong> — daily snapshots merged recency-weighted with the live EMA; one weird day can&#39;t tilt detection. TUI ML tab (<code>m</code>): learning state, live vs merged, thresholds, full history. <a href="/pingless-studios-docs/openshield-xdp/user-guide/baseline-ml">Guide</a></li><li><strong>Delete-a-day reconfiguration</strong> — a poisoned day (attack bypassed detection) can be deleted; the baseline reconfigures instantly. <code>D</code> resets today&#39;s live baseline for same-day bypasses.</li><li><strong>Baseline import/export</strong> — move trained baselines between servers.</li><li><strong>Smart multi-profile blending</strong> — multiple workload selections merge by semantics, not averages: rate ceilings = union of legit needs, scoring = strictest, FP-prone detections only where all agree.</li><li><strong>Preset retune</strong> — Balanced actually bans sustained 2× abuse; Hosting/Performance/Database bypass classes closed.</li><li><strong>Honest attack reports</strong> — median-based recovery (3s spikes no longer linger for minutes), real attacker IP counts (no more 100k phantom IPs), geo breakdown only from elevated intervals, Mbps/Kbps formatting.</li><li><strong>Alert pipeline overhaul</strong> — attack-end reports can&#39;t be lost, lifecycle alerts get queue priority, Discord 429 handling, embedded banner.</li><li><strong>Behavior engine race fixed</strong>; <code>attack_start_mono</code> preservation (the MC disconnect bug).</li></ul><h2 id="v2-3-3-—-boot-autostart-crash-immunity" tabindex="-1">v2.3.3 — Boot autostart &amp; crash-immunity <a class="header-anchor" href="#v2-3-3-—-boot-autostart-crash-immunity" aria-label="Permalink to &quot;v2.3.3 — Boot autostart &amp; crash-immunity&quot;">​</a></h2><ul><li><strong><code>openshield load -always</code></strong> — one flag enables auto-load on every boot via the systemd unit. Self-heals a missing unit file from the pristine copy in <code>/opt/openshield/lib</code>, and verifies the enable actually took.</li><li><strong>Admin IP protection, guaranteed</strong> — the loader binary (what systemd runs at boot) now also auto-whitelists your SSH source IP; the persisted entry is re-applied on every boot before the first packet is judged.</li><li><strong>Hardened systemd unit</strong> — waits for <code>network-online.target</code> (no more racing the interface at boot), and <code>StartLimitIntervalSec=0</code> means a crash loop never puts the firewall into a permanent failed state.</li><li><strong>Silent-crash immunity baked into every binary</strong> — on some kernels/hypervisors the Go runtime&#39;s async preemption killed the loader instantly with no output. All binaries now self-apply the documented workaround (<code>GODEBUG=asyncpreemptoff=1</code>) via a transparent re-exec, so manual runs are as safe as the systemd unit.</li></ul><h2 id="v2-3-2-—-cli-help-system-tui-bugfix-sweep" tabindex="-1">v2.3.2 — CLI help system &amp; TUI bugfix sweep <a class="header-anchor" href="#v2-3-2-—-cli-help-system-tui-bugfix-sweep" aria-label="Permalink to &quot;v2.3.2 — CLI help system &amp; TUI bugfix sweep&quot;">​</a></h2><ul><li><strong>Per-command help pages</strong> — <code>openshield help &lt;command&gt;</code> / <code>--help</code> anywhere, driven by one registry so overall and per-command help can never drift.</li><li><strong>18 TUI fixes</strong> — geo-tab crash on empty search, never-block input digit handling, traffic screen wraps below 140 columns, typed <code>config_update</code> replies (live config edits no longer look lost), confirm dialogs honor Ctrl+C, uptime-based health badges, narrow-terminal layout, scrollable help overlay, complete keybind docs, input validation, and more.</li></ul><h2 id="v2-3-1-—-self-traffic-exclusion-startup-warmup" tabindex="-1">v2.3.1 — Self-traffic exclusion &amp; startup warmup <a class="header-anchor" href="#v2-3-1-—-self-traffic-exclusion-startup-warmup" aria-label="Permalink to &quot;v2.3.1 — Self-traffic exclusion &amp; startup warmup&quot;">​</a></h2><ul><li><strong>Your own downloads no longer fake attacks</strong> — replies to the server&#39;s outbound connections (GeoIP updates, blocklist fetches, apt) are excluded from attack-detection and baseline-learning rates. Root-caused: the global counters ran before every exemption. <a href="/pingless-studios-docs/openshield-xdp/features/silent-guardians#your-own-downloads-never-fake-an-attack">How it works</a></li><li><strong><code>attack_warmup_sec</code></strong> (default 20) — no attack declaration in the first seconds after loader start; per-IP mitigation unaffected.</li></ul><h2 id="v2-3-0-—-smarter-feeds-bigger-maps" tabindex="-1">v2.3.0 — Smarter feeds, bigger maps <a class="header-anchor" href="#v2-3-0-—-smarter-feeds-bigger-maps" aria-label="Permalink to &quot;v2.3.0 — Smarter feeds, bigger maps&quot;">​</a></h2><ul><li><strong>Auto-fetch <code>vps</code> / <code>dedicated</code> modes</strong> — dedicated mode skips known cloud/hosting provider ranges (Cloudflare, AWS, GCP live lists + offline fallback) so customer nodes on a dedicated box are never feed-banned.</li><li><strong>List hygiene</strong> — whitelabel (never-block) syncing with the whitelist, blacklist↔whitelist conflict resolution.</li><li><strong>2M-entry ban maps</strong> (IPv4) — million-IP botnets fit with headroom (~1 GB).</li></ul><h2 id="v2-2-x-—-geo-blocking-alert-quality" tabindex="-1">v2.2.x — Geo blocking &amp; alert quality <a class="header-anchor" href="#v2-2-x-—-geo-blocking-alert-quality" aria-label="Permalink to &quot;v2.2.x — Geo blocking &amp; alert quality&quot;">​</a></h2><ul><li><strong>Geo country blocking</strong> — one keypress blocks a country; ranges resolve from MaxMind GeoLite2 into permanent subnet bans, with persisted records and one-keypress unblock. Geo analytics (top attacking countries with flags, IPs, PPS, Gbps, share %) in attack-end reports and daily/weekly/monthly reports.</li><li><strong>Ban notes</strong> — optional notes on every ban; geo blocks use them for surgical unblocking.</li><li><strong>Alert cadence rework</strong> — growing-interval progress updates, guaranteed end-of-attack delivery with the full report, oversized-forensics fallback message.</li><li><strong>Port-cap player protection</strong> — established and pre-attack sources exempt from the per-port attack cap.</li></ul><h2 id="v2-1-x-—-metrics-obfuscation-rotation-proof-caps" tabindex="-1">v2.1.x — Metrics, obfuscation, rotation-proof caps <a class="header-anchor" href="#v2-1-x-—-metrics-obfuscation-rotation-proof-caps" aria-label="Permalink to &quot;v2.1.x — Metrics, obfuscation, rotation-proof caps&quot;">​</a></h2><ul><li><strong>Metrics HTTP API</strong> — optional endpoint with everything the TUI shows; API key (yours or auto-generated), rate limits, allowlist.</li><li><strong>Obfuscated prebuilt releases</strong> — garble-built binaries, zero source in the production zip; dual packaging (bin + src).</li><li><strong>Attack per-port aggregate cap</strong> — the rotation-proof answer to spoofed floods.</li><li><strong>New-source temp bans</strong> — replaces drop-only handling of source bursts.</li><li><strong>Forensics config evidence</strong> — every attack bundle includes the config (with change timestamps) active during it.</li><li><strong>Runtime config edits persist</strong> — TUI/live edits write through to the YAML.</li></ul><h2 id="v2-0-0-—-the-sftp-fix" tabindex="-1">v2.0.0 — The SFTP fix <a class="header-anchor" href="#v2-0-0-—-the-sftp-fix" aria-label="Permalink to &quot;v2.0.0 — The SFTP fix&quot;">​</a></h2><ul><li><strong>Established-connection exemption (A2)</strong> — proven TCP connections (handshake + real data) are exempt from rate scoring. Bulk transfers — SFTP uploads, backups, replication — never get banned again. <a href="/pingless-studios-docs/openshield-xdp/features/silent-guardians#your-sftp-uploads-never-get-you-banned">The full story</a></li><li><strong>Per-port threshold overrides (C)</strong> — custom PPS/BPS limits for specific ports or port ranges, replacing both normal and attack-mode thresholds on those ports only.</li></ul>',36)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
